+const ON_SENTINEL_VISIBLE = 'OnSentinelVisible';
+
+let observer = null;
+let currentSentinel = null;
+
+export function observe(sentinel, dotNetRef) {
+    dispose();
+
+    observer = new IntersectionObserver(async (entries) => {
+        for (const entry of entries) {
+            if (entry.isIntersecting) {
+                try {
+                    await dotNetRef.invokeMethodAsync(ON_SENTINEL_VISIBLE);
+                } catch { /* circuit disconnected */ }
+            }
+        }
+    }, { rootMargin: '200px' });
+
+    currentSentinel = sentinel;
+    observer.observe(sentinel);
+}
+
+export function unobserve() {
+    if (observer && currentSentinel) {
+        observer.unobserve(currentSentinel);
+    }
+}
+
+export function dispose() {
+    if (observer) {
+        observer.disconnect();
+        observer = null;
+        currentSentinel = null;
+    }
+}
